import { ChangeDetectionStrategy, Component, booleanAttribute, input } from '@angular/core';

export type AevkoItemVariant = 'default' | 'outline' | 'muted';

@Component({
  selector: 'aevko-item',
  standalone: true,
  templateUrl: './item.component.html',
  styleUrl: './item.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[attr.data-variant]': 'variant()',
    '[attr.aria-disabled]': 'disabled() ? "true" : null',
  },
})
export class AevkoItem {
  readonly variant = input<AevkoItemVariant>('default');
  readonly disabled = input(false, { transform: booleanAttribute });
}

:host {
  align-items: center;
  border-radius: var(--aevko-radius, 0);
  display: grid;
  gap: 1rem;
  grid-template-columns: auto minmax(0, 1fr) auto;
  min-height: 3.5rem;
  padding: 0.75rem;
}
:host([data-variant='outline']) {
  border: 1px solid var(--aevko-border, #c7c7c7);
}
:host([data-variant='muted']) {
  background: var(--aevko-surface, #f2f2f2);
}
:host([aria-disabled='true']) {
  opacity: 0.55;
}
.copy {
  display: grid;
  gap: 0.2rem;
}
.copy :where([aevkoItemTitle]) {
  font-weight: 700;
}
.copy :where([aevkoItemDescription]) {
  color: var(--aevko-muted, #5f5f5f);
  font-size: 0.875rem;
}
.action {
  display: flex;
}
